async () => {
  // Task 8 measurement snippet (docs/plans/2026-09-29-gpu-profiler-timestamp-writes-plan.md), plus:
  // the return value of enableGpuProfiling(), every console.warn/error in the window (Safari
  // under WebDriver has no console), the discard counters before enabling, the live graph.
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const engine = window.__hyperion;
  const profiler = () => engine.renderer?.graph?.profiler ?? null;
  const warnings = [];
  const errors = [];
  const warn = console.warn;
  const error = console.error;
  console.warn = (...a) => { warnings.push(a.map(String).join(' ')); warn(...a); };
  console.error = (...a) => { errors.push(a.map(String).join(' ')); error(...a); };
  try {
    const beforeEnable = profiler() ? { ...profiler().discardReasons } : null;
    const enabled = engine.enableGpuProfiling();
    if (!enabled) return { enabled, gpuProfilingSupported: engine.gpuProfilingSupported, beforeEnable, warnings, errors };
    const t0 = performance.now();
    let rafs = 0;
    let counting = true;
    const count = () => { rafs++; if (counting) requestAnimationFrame(count); };
    requestAnimationFrame(count);
    await sleep(1000); // warm-up
    const warm = { ...profiler().discardReasons };
    while ((engine.getGpuFrameTiming()?.sampleCount ?? 0) < 120 && performance.now() - t0 < 15000) await sleep(100);
    counting = false;
    const elapsedMs = performance.now() - t0;
    const timings = engine.getGpuTimings();
    const frame = engine.getGpuFrameTiming();
    await sleep(2000);
    const again = engine.getGpuTimings();
    const frameAgain = engine.getGpuFrameTiming();
    const after = { ...profiler().discardReasons };
    const skippedFrames = profiler().skippedFrames;
    const graphOrder = engine.renderer.graph.executionOrder;
    engine.disableGpuProfiling();
    return {
      enabled, gpuProfilingSupported: engine.gpuProfilingSupported,
      fps: (rafs * 1000) / elapsedMs, elapsedMs, frame, timings, again, frameAgain, skippedFrames,
      discardReasonsBeforeEnable: beforeEnable, discardReasons: after,
      discardsAfterWarmUp: Object.fromEntries(Object.keys(after).map((k) => [k, after[k] - warm[k]])),
      warnings: warnings.filter((w) => w.includes('GPU profiling')),
      allWarnings: warnings, errors,
      graphOrder, lightingBackend: engine.lighting.backend, lightingEnabled: engine.renderer.lightingEnabled,
      canvas: [engine.renderer ? document.getElementById('canvas').width : null, document.getElementById('canvas').height],
      visibility: document.visibilityState,
    };
  } finally {
    console.warn = warn;
    console.error = error;
  }
}
